{
  "scenes": [
    {
      "id": 1,
      "imgPrompt": "Sweaty young woman in summer heat, grimacing under bright sun, suddenly holding a compact white portable fan to her cheek, feeling cool relief, natural sunlight, sweat details, shallow depth of field, commercial product advertisement photography, high resolution",
      "vo": "Summer heat ruining your day? Meet your instant cool fix.",
      "zh": "夏日酷热让你崩溃？即刻清爽，就此相见。",
      "dur": 4
    },
    {
      "id": 2,
      "imgPrompt": "Extreme close-up product photography of a sleek portable mini fan on a clean pastel blue studio background, USB-C charging port clearly visible, three tactile speed buttons, fan blades spinning rapidly with slight motion blur, soft edge lighting, crisp reflections, commercial advertising style, ultra detailed",
      "vo": "USB rechargeable. Three power levels. Whisper quiet operation.",
      "zh": "USB充电，三档强劲风力，运行静谧如耳语。",
      "dur": 5
    },
    {
      "id": 3,
      "imgPrompt": "Young man walking through a sunlit park, smiling confidently, holding the compact portable fan close to his face, white fan visible in hand, light summer outfit, bokeh background of trees, bright cheerful color grading, lifestyle advertising photography, product in focus",
      "vo": "Stay cool wherever life takes you. Grab yours today.",
      "zh": "无论身在何处，皆享清凉。今天就把清凉带回家。",
      "dur": 4
    }
  ]
}
